import { cookies, headers } from 'next/headers'

const DEFAULT_THEME = 'light'

// Parses an Accept-Language header (e.g. "fr-CH, fr;q=0.9, en;q=0.8") and
// returns the highest-weighted language tag, or null if the header is absent.
function preferredLanguage(acceptLanguage: string | null): string | null {
  if (!acceptLanguage) return null

  const ranked = acceptLanguage
    .split(',')
    .map((part, index) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params
        .map((p) => p.trim())
        .find((p) => p.startsWith('q='))
      const quality = qParam ? Number.parseFloat(qParam.slice(2)) : 1
      return {
        tag: tag.trim(),
        quality: Number.isNaN(quality) ? 0 : quality,
        index,
      }
    })
    .filter(({ tag, quality }) => tag !== '' && quality > 0)
    .sort((a, b) => b.quality - a.quality || a.index - b.index)

  return ranked[0]?.tag ?? null
}

export default async function UserPreferences() {
  const [cookieStore, headerList] = await Promise.all([cookies(), headers()])

  const theme = cookieStore.get('theme')?.value || DEFAULT_THEME
  const language = preferredLanguage(headerList.get('accept-language'))

  return (
    <dl>
      <dt>Theme</dt>
      <dd data-testid="theme">{theme}</dd>

      <dt>Preferred language</dt>
      <dd data-testid="language">{language ?? 'Not specified'}</dd>
    </dl>
  )
}

